function model(p) {
  // Three (or four) architecture options scored 1-10 on five criteria, a weighting profile that says what the
  // organisation cares about, a weighted score out of 100 per option and a target the chosen option must clear.
  // Options, scores and weights are illustrative; the lesson is about reading the comparison, not the verdict.
  const profile = Math.max(0, Math.min(3, Math.round(p.profile)));
  const target = Math.max(50, Math.min(80, Math.round(p.target / 5) * 5));
  const statusQuo = Math.round(p.statusQuo) === 1;
  const criteria = [
    { id: 'cost', label: 'Cost (3 years)', short: 'Cost' },
    { id: 'speed', label: 'Time to value', short: 'Speed' },
    { id: 'compliance', label: 'Compliance fit', short: 'Compliance' },
    { id: 'flex', label: 'Flexibility', short: 'Flexibility' },
    { id: 'ops', label: 'Operational burden (low is good)', short: 'Operations' }
  ];
  const profiles = [
    { id: 'balanced', label: 'Balanced', w: [1, 1, 1, 1, 1], note: 'Every criterion counts the same.' },
    { id: 'cost', label: 'Cost first', w: [3, 1, 1, 0.5, 1.5], note: 'Cost weighs three times a normal criterion; flexibility half.' },
    { id: 'compliance', label: 'Compliance first', w: [1, 0.5, 3, 1, 1.5], note: 'Compliance fit weighs three times; speed half.' },
    { id: 'speed', label: 'Speed first', w: [0.5, 3, 1, 1, 1], note: 'Time to value weighs three times; cost half.' }
  ];
  const prof = profiles[profile];
  // scores: higher is better on every axis (operational burden is scored as its inverse)
  const O = [
    { id: 'native', label: 'Native platform tools', s: [8, 8, 7, 4, 8], blurb: 'configure what the platform already offers' },
    { id: 'ipaas', label: 'Integration platform (iPaaS)', s: [6, 7, 8, 7, 6], blurb: 'a managed integration layer with connectors' },
    { id: 'custom', label: 'Custom services', s: [3, 4, 6, 10, 3], blurb: 'build and run bespoke services' },
    { id: 'manual', label: 'Keep it manual', s: [10, 10, 1, 1, 3], blurb: 'spreadsheets and people, no change' }
  ].slice(0, statusQuo ? 4 : 3);
  const wsum = prof.w.reduce((a, v) => a + v, 0);
  const options = O.map((o, k) => {
    const weighted = o.s.map((v, i) => v * prof.w[i]), score = Math.round(100 * weighted.reduce((a, v) => a + v, 0) / (10 * wsum));
    const mean = +(o.s.reduce((a, v) => a + v, 0) / o.s.length).toFixed(2);
    return { ...o, k, weighted: weighted.map(v => +v.toFixed(2)), score, mean, clears: score >= target, band: score >= 70 ? 'good' : score >= 50 ? 'ok' : 'poor' };
  });
  const ranked = options.slice().sort((a, b) => b.score - a.score || a.k - b.k);
  const winner = ranked[0], runnerUp = ranked[1], margin = winner.score - runnerUp.score;
  const best = criteria.map((c, i) => options.slice().sort((a, b) => b.s[i] - a.s[i])[0].id);
  const steps = [
    { id: 'axes', t: 0, title: 'Five criteria, scored 1 to 10', note: 'Each option is scored on cost, time to value, compliance fit, flexibility and operational burden. No option wins everywhere: the criteria are revealed one by one.' },
    { id: 'weights', t: 6, title: 'Weights: ' + prof.label, note: prof.note + ' The weighted score out of 100 is what the decision is made on, so the weights are the decision.' },
    { id: 'verdict', t: 10, title: winner.label + ' scores ' + winner.score + (winner.clears ? ', above the target of ' + target : ', below the target of ' + target), note: margin >= 10 ? 'A clear lead of ' + margin + ' points over ' + runnerUp.label + '.' : 'Only ' + margin + ' point' + (margin === 1 ? '' : 's') + ' ahead of ' + runnerUp.label + ': change one weight and the verdict can flip.' },
    { id: 'sowhat', t: 14, title: 'So what for the decision', note: 'Show the raw scores, show the weights, then the verdict, in that order. A single number hides that the ranking belongs to the weights.' }
  ];
  const summary = prof.label + ': ' + ranked.map(o => o.label + ' ' + o.score).join(', ') + '; target ' + target + ', ' + options.filter(o => o.clears).length + ' of ' + options.length + ' clear it.';
  return { profile: prof, profiles: profiles.map(x => x.label), target, criteria, options, ranked: ranked.map(o => o.id), winner: winner.id, runnerUp: runnerUp.id, margin, best, steps, duration: 17, markers: steps.map(s => s.t), summary };
}

