function check(p) {
  const m = model(p), w = m.profile.w, wsum = w.reduce((a, v) => a + v, 0);
  // Weighted scores recomputed from the raw scores and the weights; winner is the top score; bands and target flags follow
  const scoresOk = m.options.every(o => o.score === Math.round(100 * o.s.reduce((a, v, i) => a + v * w[i], 0) / (10 * wsum)) && o.score >= 0 && o.score <= 100);
  const sorted = m.options.slice().sort((a, b) => b.score - a.score || a.k - b.k);
  const winnerOk = sorted[0].id === m.winner && sorted[1].id === m.runnerUp && m.margin === sorted[0].score - sorted[1].score && JSON.stringify(sorted.map(o => o.id)) === JSON.stringify(m.ranked);
  const flagsOk = m.options.every(o => o.clears === (o.score >= m.target) && o.band === (o.score >= 70 ? 'good' : o.score >= 50 ? 'ok' : 'poor'));
  // Raw scores do not depend on the profile; under the balanced profile the ranking equals the ranking by mean
  const other = model(Object.assign({}, p, { profile: (Math.round(p.profile) + 1) % 4 }));
  const rawOk = m.options.every((o, k) => JSON.stringify(o.s) === JSON.stringify(other.options[k].s));
  const bal = model(Object.assign({}, p, { profile: 0 })), byMean = bal.options.slice().sort((a, b) => b.mean - a.mean || a.k - b.k).map(o => o.id);
  const balancedOk = JSON.stringify(byMean) === JSON.stringify(bal.ranked);
  const countOk = m.options.length === (Math.round(p.statusQuo) === 1 ? 4 : 3) && m.criteria.length === 5 && m.best.length === 5;
  const pass = scoresOk && winnerOk && flagsOk && rawOk && balancedOk && countOk;
  return {
    pass,
    detail: m.profile.label + ': ' + m.options.map(o => o.label + ' ' + o.score).join(', ') + (scoresOk ? '' : ' (weighted scores off)') + '; winner ' + m.winner + ' by ' + m.margin + (winnerOk ? '' : ' (ranking wrong)') +
      '; ' + m.options.filter(o => o.clears).length + ' clear the target of ' + m.target + '; raw scores independent of the profile' + (rawOk ? '.' : ' (they changed).')
  };
}
